"""GENERATED by src/migration_window_gen.py from stable_sets.kern and farsighted_refusal.fkern -- do not edit.

kern_mw / fkern_mw are the originals with three added per-generation records (modal outcome, encounter mass on
efficient outcomes, encounter mass on fair pairs), appended to the original return tuples.  The random-number stream is
unchanged (tests/test_migration_window.py checks draw-for-draw identity with the originals)."""
import numpy as np
from numba import njit
import stable_sets as SS
import dominance_contracts as DC
from stable_sets import _fit_full, _setact, _classify, _parent, _closed, _code, _others
from farsighted_refusal import _gcounts, _ftypeid, reader_values, _consent


@njit(cache=True)
def _rec(dist, nout, ISMEM, TOT, modal, effm, fairm, g, i):
    mx = -1.0; arg = 0; ef = 0.0; fm = 0.0
    for z in range(nout):
        if dist[z] > mx:
            mx = dist[z]; arg = z
        if TOT[z] > 0.999:
            ef += dist[z]
        if ISMEM[z]:
            fm += dist[z]
    modal[g, i] = arg; effm[g, i] = ef; fairm[g, i] = fm


@njit(cache=True)
def kern_mw(J, PAY, VEC, ISMEM, TOT, init, N, w, m, seed, H, close_every, hrec, evcap):
    """eps = 0 island lottery, three slot populations per island; the birth-death law and the random-draw order of
    sog_lottery.kern with a check every generation.  Returns status (1 globally closed, 5 every island locally
    closed at m = 0, 4 censored at H), the stop generation, final counts, the per-generation island classes
    cls[g, i] (outcome id, nout = member-mixed, nout + 1 = other-mixed), efficiency and outcome distributions at the
    generations in hrec, the dominance-change event log (gen, island, slot, old, new, intro, t10, dpay), the number
    of events (> evcap = overflow) and the number of migrant births."""
    np.random.seed(seed)
    I = init.shape[0]; K = init.shape[2]
    nout = ISMEM.shape[0]
    counts = init.copy()
    pres = np.zeros((I, 3, K), np.int64); npres = np.zeros((I, 3), np.int64); pos = -np.ones((I, 3, K), np.int64)
    glob = np.zeros((3, K), np.int64)
    F = np.zeros((I, 3, K))
    intro = np.full((I, 3, K), -2, np.int64)
    t10 = np.full((I, 3, K), -1, np.int64)
    for i in range(I):
        for s in range(3):
            for k in range(K):
                if counts[i, s, k] > 0:
                    pres[i, s, npres[i, s]] = k; pos[i, s, k] = npres[i, s]; npres[i, s] += 1
                    glob[s, k] += counts[i, s, k]
                    intro[i, s, k] = -1
                    if counts[i, s, k] * 10 >= N:
                        t10[i, s, k] = 0
    for i in range(I):
        for s in range(3):
            for t in range(npres[i, s]):
                k = pres[i, s, t]
                F[i, s, k] = _fit_full(J, PAY, counts, pres, npres, i, s, k)
    NU = 3 * I
    act = np.arange(NU); apos = np.arange(NU); nact = 0
    for u in range(NU):
        if npres[u // 3, u % 3] > 1:
            nact = _setact(u, True, act, apos, nact)
    cls = np.zeros((H + 1, I), np.int16)
    mw_modal = np.zeros((H + 1, I), np.int8); mw_effm = np.zeros((H + 1, I), np.float32)
    mw_fairm = np.zeros((H + 1, I), np.float32)
    nh = hrec.shape[0]
    effrec = np.zeros((nh, I)); distrec = np.zeros((nh, I, nout))
    dist = np.zeros(nout)
    dom = -np.ones((I, 3), np.int64)
    ev = np.zeros((evcap, 8))
    nev = 0
    N2 = float(N) * N
    UN = NU * N
    mm = m if I > 1 else 0.0
    for i in range(I):
        c, e = _classify(J, VEC, ISMEM, TOT, counts, pres, npres, i, N, dist, nout)
        cls[0, i] = c
        _rec(dist, nout, ISMEM, TOT, mw_modal, mw_effm, mw_fairm, 0, i)
        for s in range(3):
            for t in range(npres[i, s]):
                k = pres[i, s, t]
                if 2 * counts[i, s, k] > N:
                    dom[i, s] = k
            if dom[i, s] >= 0 and nev < evcap:
                ev[nev, 0] = 0; ev[nev, 1] = i; ev[nev, 2] = s; ev[nev, 3] = -1; ev[nev, 4] = dom[i, s]
                ev[nev, 5] = -1; ev[nev, 6] = 0; ev[nev, 7] = np.nan
                nev += 1
    b = 0
    g = 0
    hi = 0
    nextchk = UN
    status = 4; stop_gen = H
    nmig = 0
    total = H * UN
    cls0 = np.zeros(K, np.int64); cls1 = np.zeros(K, np.int64); cls2 = np.zeros(K, np.int64)
    while True:
        pa = (nact + (NU - nact) * mm) / NU
        if pa <= 0.0:
            G = total + 1
        elif pa >= 1.0:
            G = 0
        else:
            uu = np.random.random()
            G = int(np.log(1.0 - uu) / np.log(1.0 - pa))
        if b + G >= nextchk:
            b = nextchk
            g += 1
            for i in range(I):
                c, e = _classify(J, VEC, ISMEM, TOT, counts, pres, npres, i, N, dist, nout)
                cls[g, i] = c
                _rec(dist, nout, ISMEM, TOT, mw_modal, mw_effm, mw_fairm, g, i)
                if hi < nh and hrec[hi] == g:
                    effrec[hi, i] = e
                    for z in range(nout):
                        distrec[hi, i, z] = dist[z]
                for s in range(3):
                    nd = -1
                    for t in range(npres[i, s]):
                        k = pres[i, s, t]
                        if t10[i, s, k] < 0 and counts[i, s, k] * 10 >= N:
                            t10[i, s, k] = g
                        if 2 * counts[i, s, k] > N:
                            nd = k
                    if nd >= 0 and nd != dom[i, s]:
                        # a change of the slot's (last) majority class; dom keeps the last majority class
                        if nev < evcap:
                            ev[nev, 0] = g; ev[nev, 1] = i; ev[nev, 2] = s; ev[nev, 3] = dom[i, s]; ev[nev, 4] = nd
                            ev[nev, 5] = intro[i, s, nd]; ev[nev, 6] = t10[i, s, nd]
                            if dom[i, s] >= 0:
                                ev[nev, 7] = (_fit_full(J, PAY, counts, pres, npres, i, s, nd) - _fit_full(J, PAY, counts, pres, npres, i, s, dom[i, s])) / N2
                            else:
                                ev[nev, 7] = np.nan
                        nev += 1
                        dom[i, s] = nd
            if hi < nh and hrec[hi] == g:
                hi += 1
            done = False
            if g % close_every == 0 or g == H:
                if mm > 0.0:
                    n0 = 0; n1 = 0; n2 = 0
                    for k in range(K):
                        if glob[0, k] > 0:
                            cls0[n0] = k; n0 += 1
                        if glob[1, k] > 0:
                            cls1[n1] = k; n1 += 1
                        if glob[2, k] > 0:
                            cls2[n2] = k; n2 += 1
                    if _closed(J, cls0, n0, cls1, n1, cls2, n2):
                        status = 1; stop_gen = g; done = True
                else:
                    allc = True
                    for i in range(I):
                        if not _closed(J, pres[i, 0], npres[i, 0], pres[i, 1], npres[i, 1], pres[i, 2], npres[i, 2]):
                            allc = False; break
                    if allc:
                        status = 5; stop_gen = g; done = True
            if done or g >= H:
                break
            nextchk = (g + 1) * UN
            continue
        b = b + G + 1
        if np.random.random() * pa * NU < nact:
            u = act[np.random.randint(nact)]
            mig = mm > 0.0 and np.random.random() < mm
        else:
            u = act[nact + np.random.randint(NU - nact)]
            mig = True
        i = u // 3; s = u % 3
        src = i
        if mig:
            src = np.random.randint(I - 1)
            if src >= i: src += 1
            nmig += 1
        child = _parent(F, counts, pres, npres, src, s, N2, w)
        r = np.random.randint(N); acc = 0; victim = pres[i, s, 0]
        for t in range(npres[i, s]):
            k = pres[i, s, t]; acc += counts[i, s, k]
            if r < acc:
                victim = k; break
        if victim == child:
            continue
        counts[i, s, victim] -= 1; glob[s, victim] -= 1
        if counts[i, s, victim] == 0:
            p = pos[i, s, victim]; last = pres[i, s, npres[i, s] - 1]
            pres[i, s, p] = last; pos[i, s, last] = p; pos[i, s, victim] = -1; npres[i, s] -= 1
            intro[i, s, victim] = -2; t10[i, s, victim] = -1
        new = counts[i, s, child] == 0
        if new:
            pres[i, s, npres[i, s]] = child; pos[i, s, child] = npres[i, s]; npres[i, s] += 1
            intro[i, s, child] = g + 1
        counts[i, s, child] += 1; glob[s, child] += 1
        o1, o2 = _others(s)
        for sa in (o1, o2):
            sb = o1 + o2 - sa
            for ta in range(npres[i, sa]):
                k = pres[i, sa, ta]
                v = 0.0
                for tb in range(npres[i, sb]):
                    q = pres[i, sb, tb]
                    if s < sb:
                        v += counts[i, sb, q] * (PAY[_code(J, sa, k, child, q), sa] - PAY[_code(J, sa, k, victim, q), sa])
                    else:
                        v += counts[i, sb, q] * (PAY[_code(J, sa, k, q, child), sa] - PAY[_code(J, sa, k, q, victim), sa])
                F[i, sa, k] += v
        if new:
            F[i, s, child] = _fit_full(J, PAY, counts, pres, npres, i, s, child)
        nact = _setact(u, npres[i, s] > 1, act, apos, nact)
    for gg in range(stop_gen + 1, H + 1):
        for i in range(I):
            cls[gg, i] = cls[stop_gen, i]
            mw_modal[gg, i] = mw_modal[stop_gen, i]; mw_effm[gg, i] = mw_effm[stop_gen, i]; mw_fairm[gg, i] = mw_fairm[stop_gen, i]
    for z in range(hi, nh):
        if hrec[z] > stop_gen:
            for i in range(I):
                c, e = _classify(J, VEC, ISMEM, TOT, counts, pres, npres, i, N, dist, nout)
                effrec[z, i] = e
                for zz in range(nout):
                    distrec[z, i, zz] = dist[zz]
    return status, stop_gen, counts, cls, effrec, distrec, ev[:min(nev, evcap)], nev, nmig, mw_modal, mw_effm, mw_fairm


@njit(cache=True)
def fkern_mw(J, PAY, VEC, ISMEM, TOT, tcount0, TK, TO, TG, TPC, TMAP, ntypes, Kmax, NG, N, w, m, seed, H,
          close_every, hrec, nu, CS, CD, CACT, CX, GKIND, GTAB, KRTAB, PROPM, UPAY, rdelta, stop_closed, rec_every,
          evcap, cevcap):
    """eps = 0 island lottery with genotypes (k, o, g) and contract events (menu F, beta = 1, public consent by guard).
    Births, migration, classification and closure exactly as dominance_contracts.dkern."""
    np.random.seed(seed)
    I = tcount0.shape[0]; Tcap = tcount0.shape[2]; PCn = J.shape[0]
    nout = ISMEM.shape[0]
    tcount = tcount0.copy()
    tpres = np.zeros((I, 3, Tcap), np.int64); tnpres = np.zeros((I, 3), np.int64); tpos = -np.ones((I, 3, Tcap), np.int64)
    pcount = np.zeros((I, 3, PCn), np.int64); ppres = np.zeros((I, 3, PCn), np.int64)
    pnpres = np.zeros((I, 3), np.int64); ppos = -np.ones((I, 3, PCn), np.int64)
    glob = np.zeros((3, PCn), np.int64)
    Fp = np.zeros((I, 3, PCn))
    introg = np.full((I, 3, PCn), -2, np.int64); introc = np.zeros((I, 3, PCn), np.int64)
    for i in range(I):
        for s in range(3):
            for t in range(Tcap):
                if tcount[i, s, t] > 0:
                    tpres[i, s, tnpres[i, s]] = t; tpos[i, s, t] = tnpres[i, s]; tnpres[i, s] += 1
                    pcount[i, s, TPC[s, t]] += tcount[i, s, t]
            for pc in range(PCn):
                if pcount[i, s, pc] > 0:
                    ppres[i, s, pnpres[i, s]] = pc; ppos[i, s, pc] = pnpres[i, s]; pnpres[i, s] += 1
                    glob[s, pc] += pcount[i, s, pc]
                    introg[i, s, pc] = -1; introc[i, s, pc] = 0
    for i in range(I):
        for s in range(3):
            for t in range(pnpres[i, s]):
                pc = ppres[i, s, t]
                Fp[i, s, pc] = SS._fit_full(J, PAY, pcount, ppres, pnpres, i, s, pc)
    NU = 3 * I
    act = np.arange(NU); apos = np.arange(NU); nact = 0
    for u in range(NU):
        if tnpres[u // 3, u % 3] > 1:
            nact = SS._setact(u, True, act, apos, nact)
    cls = np.zeros((H + 1, I), np.int16)
    mw_modal = np.zeros((H + 1, I), np.int8); mw_effm = np.zeros((H + 1, I), np.float32)
    mw_fairm = np.zeros((H + 1, I), np.float32)
    nh = hrec.shape[0]
    effrec = np.zeros((nh, I)); distrec = np.zeros((nh, I, nout))
    dist = np.zeros(nout)
    dom = -np.ones((I, 3), np.int64)
    ev = np.zeros((evcap, 8)); nev = 0
    cev = np.zeros((cevcap, 16)); ncev = 0
    cnt = np.zeros((I, 8), np.int64)      # draws, null, -, consulted, refused, installed, infeasible, overflow
    refby = np.zeros((I, NG), np.int64)   # refusals by the drawn individual's guard
    nrec = H // rec_every + 1
    gfreq = np.zeros((nrec, I, 3, NG), np.float32)
    gc = np.zeros((3, NG), np.int64)
    rdec = np.zeros(2, np.bool_)
    nsolve = 0
    N2 = float(N) * N
    UN = NU * N
    mm = m if I > 1 else 0.0
    overflow = False
    hasreader = False
    for g_ in range(NG):
        if GKIND[g_] == 1:
            hasreader = True
    for i in range(I):
        c, e = SS._classify(J, VEC, ISMEM, TOT, pcount, ppres, pnpres, i, N, dist, nout)
        cls[0, i] = c
        _rec(dist, nout, ISMEM, TOT, mw_modal, mw_effm, mw_fairm, 0, i)
        for s in range(3):
            for t in range(pnpres[i, s]):
                pc = ppres[i, s, t]
                if 2 * pcount[i, s, pc] > N:
                    dom[i, s] = pc
            if dom[i, s] >= 0 and nev < evcap:
                ev[nev, 0] = 0; ev[nev, 1] = i; ev[nev, 2] = s; ev[nev, 3] = -1; ev[nev, 4] = dom[i, s]
                ev[nev, 5] = -1; ev[nev, 6] = 0; ev[nev, 7] = np.nan
                nev += 1
    for i in range(I):
        _gcounts(tcount, tpres, tnpres, TG, i, NG, gc)
        for s in range(3):
            for g_ in range(NG):
                gfreq[0, i, s, g_] = gc[s, g_] / N
    b = 0
    g = 0
    hi = 0
    nextchk = UN
    status = 4; stop_gen = H
    nmig = 0
    total = H * UN
    cls0 = np.zeros(PCn, np.int64); cls1 = np.zeros(PCn, np.int64); cls2 = np.zeros(PCn, np.int64)
    mvt = np.zeros(Tcap, np.int64); mvn = np.zeros(Tcap, np.int64); tmpc = np.zeros(Tcap, np.int64)
    while True:
        pa = (nact + (NU - nact) * mm) / NU
        if pa <= 0.0:
            G = total + 1
        elif pa >= 1.0:
            G = 0
        else:
            uu = np.random.random()
            G = int(np.log(1.0 - uu) / np.log(1.0 - pa))
        if b + G >= nextchk:
            b = nextchk
            g += 1
            for i in range(I):
                c, e = SS._classify(J, VEC, ISMEM, TOT, pcount, ppres, pnpres, i, N, dist, nout)
                cls[g, i] = c
                _rec(dist, nout, ISMEM, TOT, mw_modal, mw_effm, mw_fairm, g, i)
                if hi < nh and hrec[hi] == g:
                    effrec[hi, i] = e
                    for z in range(nout):
                        distrec[hi, i, z] = dist[z]
                for s in range(3):
                    nd = -1
                    for t in range(pnpres[i, s]):
                        pc = ppres[i, s, t]
                        if 2 * pcount[i, s, pc] > N:
                            nd = pc
                    if nd >= 0 and nd != dom[i, s]:
                        if nev < evcap:
                            ev[nev, 0] = g; ev[nev, 1] = i; ev[nev, 2] = s; ev[nev, 3] = dom[i, s]; ev[nev, 4] = nd
                            ev[nev, 5] = introg[i, s, nd]; ev[nev, 6] = introc[i, s, nd]
                            if dom[i, s] >= 0:
                                ev[nev, 7] = (SS._fit_full(J, PAY, pcount, ppres, pnpres, i, s, nd)
                                              - SS._fit_full(J, PAY, pcount, ppres, pnpres, i, s, dom[i, s])) / N2
                            else:
                                ev[nev, 7] = np.nan
                        nev += 1
                        dom[i, s] = nd
            if hi < nh and hrec[hi] == g:
                hi += 1
            if g % rec_every == 0:
                rr_ = g // rec_every
                for i in range(I):
                    _gcounts(tcount, tpres, tnpres, TG, i, NG, gc)
                    for s in range(3):
                        for g_ in range(NG):
                            gfreq[rr_, i, s, g_] = gc[s, g_] / N
            # contract events
            if nu > 0.0 and g < H:
                for i in range(I):
                    if np.random.random() >= nu:
                        continue
                    cnt[i, 0] += 1
                    kap = np.random.randint(CS.shape[0])
                    s0 = CS[kap, 0]; s1 = CS[kap, 1]; d0 = CD[kap, 0]; d1 = CD[kap, 1]
                    if d0 + d1 > 6:
                        cnt[i, 6] += 1; cnt[i, 1] += 1
                        continue
                    y0 = DC._slot_mean(Fp, pcount, ppres, pnpres, i, s0, N, N2)
                    y1 = DC._slot_mean(Fp, pcount, ppres, pnpres, i, s1, N, N2)
                    if not (d0 / 6.0 > y0 + 1e-9 and d1 / 6.0 > y1 + 1e-9):
                        cnt[i, 1] += 1
                        continue
                    cc_, e_ = SS._classify(J, VEC, ISMEM, TOT, pcount, ppres, pnpres, i, N, dist, nout)
                    modal = 0; mx = -1.0
                    for z in range(nout):
                        if dist[z] > mx:
                            mx = dist[z]; modal = z
                    _gcounts(tcount, tpres, tnpres, TG, i, NG, gc)
                    # reader decisions for the two member slots (if a reader is present in that slot)
                    rdec[0] = False; rdec[1] = False
                    if hasreader:
                        for z in range(2):
                            sz = s0 if z == 0 else s1
                            pres = False
                            for g_ in range(NG):
                                if GKIND[g_] == 1 and gc[sz, g_] > 0:
                                    pres = True
                            if pres:
                                Wr = reader_values(gc, N, GKIND, GTAB, KRTAB, PROPM, CS, CX, UPAY, rdelta, sz)
                                nsolve += 1
                                rdec[z] = Wr[CX[kap]] > Wr[modal]
                    need = False
                    for z in range(2):
                        sz = s0 if z == 0 else s1
                        for g_ in range(NG):
                            if gc[sz, g_] > 0 and not _consent(g_, modal, kap, z, GKIND, GTAB, rdec):
                                need = True
                    refused = False
                    gd0 = -1; gd1 = -1; c0 = 1; c1 = 1
                    if need:
                        cnt[i, 3] += 1
                        for z in range(2):
                            sz = s0 if z == 0 else s1
                            r_ = np.random.randint(N); acc = 0; tv = tpres[i, sz, 0]
                            for t in range(tnpres[i, sz]):
                                tt = tpres[i, sz, t]; acc += tcount[i, sz, tt]
                                if r_ < acc:
                                    tv = tt; break
                            gz = TG[sz, tv]
                            cz = _consent(gz, modal, kap, z, GKIND, GTAB, rdec)
                            if z == 0:
                                gd0 = gz; c0 = 1 if cz else 0
                            else:
                                gd1 = gz; c1 = 1 if cz else 0
                            if not cz:
                                refused = True
                                refby[i, gz] += 1
                    row = ncev
                    if ncev < cevcap:
                        cev[row, 0] = g; cev[row, 1] = i; cev[row, 2] = kap; cev[row, 4] = cc_; cev[row, 5] = modal
                        cev[row, 6] = y0; cev[row, 7] = y1; cev[row, 8] = gd0; cev[row, 9] = gd1
                        cev[row, 10] = 1.0 if need else 0.0; cev[row, 11] = c0; cev[row, 12] = c1
                    ncev += 1
                    if refused:
                        cnt[i, 4] += 1
                        if row < cevcap:
                            cev[row, 3] = 1
                        continue
                    for z in range(2):
                        sz = s0 if z == 0 else s1
                        az = CACT[kap, z]
                        nm = 0
                        for t in range(tnpres[i, sz]):
                            tt = tpres[i, sz, t]
                            mvt[nm] = tt; mvn[nm] = tcount[i, sz, tt]; nm += 1
                        for q in range(nm):
                            if mvn[q] == 0:
                                continue
                            tt = mvt[q]
                            nt = _ftypeid(sz, TK[sz, tt], az, TG[sz, tt], NG, Kmax, TK, TO, TG, TPC, TMAP, ntypes)
                            if nt < 0:
                                overflow = True
                                break
                            if nt == tt:
                                continue
                            DC._tsub(i, sz, tt, mvn[q], tcount, tpres, tnpres, tpos)
                            DC._tadd(i, sz, nt, mvn[q], tcount, tpres, tnpres, tpos)
                            pco = TPC[sz, tt]; pcn = TPC[sz, nt]
                            if pco != pcn:
                                DC._psub(i, sz, pco, mvn[q], pcount, ppres, pnpres, ppos, glob, introg)
                                DC._padd(i, sz, pcn, mvn[q], pcount, ppres, pnpres, ppos, glob, introg, introc, g, 2)
                        nact = SS._setact(3 * i + sz, tnpres[i, sz] > 1, act, apos, nact)
                    if overflow:
                        cnt[i, 7] += 1
                        break
                    for s in range(3):
                        for t in range(pnpres[i, s]):
                            pc = ppres[i, s, t]
                            Fp[i, s, pc] = SS._fit_full(J, PAY, pcount, ppres, pnpres, i, s, pc)
                    cnt[i, 5] += 1
                    if row < cevcap:
                        cev[row, 3] = 2
                if overflow:
                    status = 9; stop_gen = g
                    break
            done = False
            if stop_closed and (g % close_every == 0 or g == H):
                if mm > 0.0:
                    n0 = 0; n1 = 0; n2 = 0
                    for k in range(PCn):
                        if glob[0, k] > 0:
                            cls0[n0] = k; n0 += 1
                        if glob[1, k] > 0:
                            cls1[n1] = k; n1 += 1
                        if glob[2, k] > 0:
                            cls2[n2] = k; n2 += 1
                    if SS._closed(J, cls0, n0, cls1, n1, cls2, n2):
                        status = 1; stop_gen = g; done = True
                else:
                    allc = True
                    for i in range(I):
                        if not SS._closed(J, ppres[i, 0], pnpres[i, 0], ppres[i, 1], pnpres[i, 1], ppres[i, 2], pnpres[i, 2]):
                            allc = False; break
                    if allc:
                        status = 5; stop_gen = g; done = True
            if done or g >= H:
                break
            nextchk = (g + 1) * UN
            continue
        b = b + G + 1
        if np.random.random() * pa * NU < nact:
            u = act[np.random.randint(nact)]
            mig = mm > 0.0 and np.random.random() < mm
        else:
            u = act[nact + np.random.randint(NU - nact)]
            mig = True
        i = u // 3; s = u % 3
        src = i
        if mig:
            src = np.random.randint(I - 1)
            if src >= i: src += 1
            nmig += 1
        mx = -1e300
        for t in range(tnpres[src, s]):
            tt = tpres[src, s, t]
            f = Fp[src, s, TPC[s, tt]] / N2
            if f > mx: mx = f
        tot = 0.0
        for t in range(tnpres[src, s]):
            tt = tpres[src, s, t]
            tot += tcount[src, s, tt] * np.exp(w * (Fp[src, s, TPC[s, tt]] / N2 - mx))
        uu = np.random.random() * tot; acc2 = 0.0
        child = tpres[src, s, tnpres[src, s] - 1]
        for t in range(tnpres[src, s]):
            tt = tpres[src, s, t]
            acc2 += tcount[src, s, tt] * np.exp(w * (Fp[src, s, TPC[s, tt]] / N2 - mx))
            if uu <= acc2:
                child = tt; break
        r = np.random.randint(N); acc = 0; victim = tpres[i, s, 0]
        for t in range(tnpres[i, s]):
            tt = tpres[i, s, t]; acc += tcount[i, s, tt]
            if r < acc:
                victim = tt; break
        if victim == child:
            continue
        DC._tsub(i, s, victim, 1, tcount, tpres, tnpres, tpos)
        DC._tadd(i, s, child, 1, tcount, tpres, tnpres, tpos)
        pv = TPC[s, victim]; pcc = TPC[s, child]
        if pv != pcc:
            DC._psub(i, s, pv, 1, pcount, ppres, pnpres, ppos, glob, introg)
            new = pcount[i, s, pcc] == 0
            DC._padd(i, s, pcc, 1, pcount, ppres, pnpres, ppos, glob, introg, introc, g + 1, 1 if mig else 0)
            o1, o2 = SS._others(s)
            for sa in (o1, o2):
                sb = o1 + o2 - sa
                for ta in range(pnpres[i, sa]):
                    k = ppres[i, sa, ta]
                    v = 0.0
                    for tb in range(pnpres[i, sb]):
                        q = ppres[i, sb, tb]
                        if s < sb:
                            v += pcount[i, sb, q] * (PAY[SS._code(J, sa, k, pcc, q), sa] - PAY[SS._code(J, sa, k, pv, q), sa])
                        else:
                            v += pcount[i, sb, q] * (PAY[SS._code(J, sa, k, q, pcc), sa] - PAY[SS._code(J, sa, k, q, pv), sa])
                    Fp[i, sa, k] += v
            if new:
                Fp[i, s, pcc] = SS._fit_full(J, PAY, pcount, ppres, pnpres, i, s, pcc)
        nact = SS._setact(u, tnpres[i, s] > 1, act, apos, nact)
    for gg in range(stop_gen + 1, H + 1):
        for i in range(I):
            cls[gg, i] = cls[stop_gen, i]
            mw_modal[gg, i] = mw_modal[stop_gen, i]; mw_effm[gg, i] = mw_effm[stop_gen, i]; mw_fairm[gg, i] = mw_fairm[stop_gen, i]
    for z in range(hi, nh):
        if hrec[z] > stop_gen:
            for i in range(I):
                c, e = SS._classify(J, VEC, ISMEM, TOT, pcount, ppres, pnpres, i, N, dist, nout)
                effrec[z, i] = e
                for zz in range(nout):
                    distrec[z, i, zz] = dist[zz]
    return (status, stop_gen, tcount, cls, effrec, distrec, ev[:min(nev, evcap)], nev, nmig, cev[:min(ncev, cevcap)],
            ncev, cnt, gfreq, refby, nsolve, pcount), mw_modal, mw_effm, mw_fairm

